export function setupCourse(root){
 let current=0,section=true,feedback=null,lang="de",done=new Set();
 try {const saved=JSON.parse(localStorage.getItem("edl-course-v1")??"[]");if(Array.isArray(saved)) done=new Set(saved.filter(i=>Number.isInteger(i)&&i>=0&&i<lessons.length));}catch{}
 function render(nextLang){
  lang=nextLang;
  const idx={de:0,en:1,ar:2}[lang], t=ui[lang], row=lessons[current];
  const correctAt=current%2;
  const options=correctAt?[12,9]:[9,12];
  root.innerHTML='<h2>'+t[0]+'</h2><p>'+t[1]+'</p><label class="course-progress">'+t[2]+' '+done.size+'/'+lessons.length+' <progress value="'+done.size+'" max="'+lessons.length+'"></progress></label><div class="course-nav">'+lessons.map((r,i)=>'<button data-lesson="'+i+'" aria-pressed="'+(i===current)+'">'+(done.has(i)?"✓ ":"")+(i+1)+". "+r[idx]+'</button>').join("")+'</div><div class="course-layout"><figure><svg viewBox="0 0 360 178" direction="ltr" role="img" aria-label="'+row[idx]+'"><defs><pattern id="courseHatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><path d="M0 0v7" stroke="#688798"/></pattern></defs><g fill="none" stroke="#173649" stroke-width="2">'+(current===2&&!section?'<path d="M62 32h35v19h208v68H97v19H62z"/><path d="M62 69h243m-243 32h243" stroke-dasharray="4 4"/><path d="M43 85h290" class="course-axis"/>':figures[current])+'</g></svg>'+(current===2?'<button data-view aria-pressed="'+section+'">'+t[section?8:7]+'</button>':'')+''+(current===4?'<ul class="sheet-legend">'+sheetLegend[lang].map(item=>'<li><bdi>'+item+'</bdi></li>').join("")+'</ul>':'')+'</figure><article><h3>'+row[idx]+'</h3><p>'+row[3+idx]+'</p><p class="course-notes">'+lessonsExtra[lang][current]+'</p><p><strong>'+row[6+idx]+'</strong></p><div class="course-options">'+options.map((offset,i)=>'<button data-answer="'+i+'">'+row[offset+idx]+'</button>').join("")+'</div><p role="status">'+(feedback===null?"":t[feedback?3:4])+'</p>'+(current===5?'<a href="./index.html#assembly">'+t[5]+'</a>':'')+'</article></div><footer><a href="https://www.technisches-zeichnen.net/technisches-zeichnen/grundkurs-01/tz-grundkurs-01.php">'+t[6]+'</a></footer>';
 }
 root.addEventListener("click",event=>{
  const button=event.target.closest("button");if(!button)return;
  const {lesson,answer}=button.dataset;
  let selector;
  if(lesson!==undefined){current=Number(lesson);feedback=null;selector='[data-lesson="'+lesson+'"]';}
  else if(answer!==undefined){feedback=Number(answer)===current%2;if(feedback){done.add(current);try{localStorage.setItem("edl-course-v1",JSON.stringify([...done]));}catch{}}selector='[data-answer="'+answer+'"]';}
  else if(button.hasAttribute("data-view")){section=!section;selector="[data-view]";}
  if(selector){render(lang);root.querySelector(selector)?.focus();}
 });
 return render;
}
